
(async () => {
  // V37 — HORDA NOTURNA
  // Reutiliza exatamente Zombie Walk / Attack / Reaction Hit que já existiam.
  const ZOMBIE_WALK_GZ = "";
  const ZOMBIE_ATTACK_GZ = "";
  const ZOMBIE_HIT_GZ = "";
  const ZOMBIE_CRAWL_GZ = "";
  const ZOMBIE_STAND_GZ = "";

  const hudState = document.getElementById("zombieHudState");
  const hpText = document.getElementById("playerHpText");
  const hpBar = document.getElementById("playerHpBar");
  const damageFlash = document.getElementById("damageFlash");
  const status = document.getElementById("status");

  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
  const wrap = a => Math.atan2(Math.sin(a),Math.cos(a));

  async function gunzipB64(s) {
    const bin=atob(s), raw=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) raw[i]=bin.charCodeAt(i);
    const ds=new DecompressionStream("gzip");
    return await new Response(new Blob([raw]).stream().pipeThrough(ds)).arrayBuffer();
  }

  async function importFirst(urls) {
    let last;
    for(const u of urls) {
      try { return await window.__LOCAL_IMPORT(u); }
      catch(e) { last=e; }
    }
    throw last || new Error("Falha ao carregar módulo 3D.");
  }

  async function waitGame() {
    for(let i=0;i<1000;i++) {
      const g=window.gameReview;
      if (
        g?.scene && g?.player && g?.groundY &&
        g?.dayNight && g?.trueFirstPerson
      ) return g;
      await sleep(20);
    }
    throw new Error("Jogo/ciclo de tempo não ficaram disponíveis.");
  }

  function stripRootMotion(clip) {
    const c=clip.clone();
    c.tracks=c.tracks.filter(t=>{
      if(/\.scale$/i.test(t.name)) return false;
      if(/\.position$/i.test(t.name)) return false;
      return true;
    });
    c.resetDuration();
    return c;
  }

  // Crawl / stand-up need the vertical Hips movement to actually lower/raise
  // the zombie. Horizontal root motion is removed so AI still owns X/Z.
  function keepVerticalHipsMotion(clip) {
    const c=clip.clone();
    const tracks=[];

    for(const track of c.tracks) {
      if(/\.scale$/i.test(track.name)) continue;

      if(/\.position$/i.test(track.name)) {
        if(!/Hips\.position$/i.test(track.name)) continue;

        const t=track.clone();
        const values=t.values.slice();
        const size=t.getValueSize();

        if(size>=3 && values.length>=3) {
          const baseX=values[0];
          const baseZ=values[2];

          for(let i=0;i<values.length;i+=size) {
            values[i]=baseX;
            values[i+2]=baseZ;
          }
          t.values=values;
        }

        tracks.push(t);
        continue;
      }

      tracks.push(track.clone());
    }

    c.tracks=tracks;
    c.resetDuration();
    return c;
  }

  function tintZombie(THREE,root) {
    let meshes=0;
    root.traverse(o=>{
      if(!o.isMesh)return;
      meshes++;
      o.castShadow=true;
      o.receiveShadow=true;

      const mats=Array.isArray(o.material)?o.material:[o.material];
      const cloned=mats.map(m=>{
        const n=m?.clone?.() || m;
        if(n?.color) n.color.multiply(new THREE.Color(.48,.66,.42));
        if("roughness" in (n||{})) n.roughness=.96;
        if(n?.emissive){
          n.emissive.setHex(0x071006);
          n.emissiveIntensity=.16;
        }
        return n;
      });
      o.material=Array.isArray(o.material)?cloned:cloned[0];
    });
    return meshes;
  }

  function normalizeZombie(THREE,model) {
    model.rotation.y=Math.PI;
    model.updateMatrixWorld(true);

    let box=new THREE.Box3().setFromObject(model);
    const size=new THREE.Vector3();
    box.getSize(size);

    if(size.y>.001) {
      const s=1.76/size.y;
      model.scale.multiplyScalar(s);
    }

    model.updateMatrixWorld(true);
    box=new THREE.Box3().setFromObject(model);
    model.position.y-=box.min.y;
    model.updateMatrixWorld(true);
  }

  try {
    const game=await waitGame();

    const [THREE, loaderMod, skeletonMod, walkBuf, attackBuf, hitBuf, crawlBuf, standBuf] =
      await Promise.all([
        importFirst([window.FLORESTA_MODULES.three,window.FLORESTA_MODULES.three]),
        importFirst([window.FLORESTA_MODULES.FBXLoader,window.FLORESTA_MODULES.FBXLoader]),
        importFirst([window.FLORESTA_MODULES.SkeletonUtils,window.FLORESTA_MODULES.SkeletonUtils]),
        gunzipB64(ZOMBIE_WALK_GZ),
        gunzipB64(ZOMBIE_ATTACK_GZ),
        gunzipB64(ZOMBIE_HIT_GZ),
        gunzipB64(ZOMBIE_CRAWL_GZ),
        gunzipB64(ZOMBIE_STAND_GZ)
      ]);

    const {FBXLoader}=loaderMod;
    const loader=new FBXLoader();

    const walkFBX=loader.parse(walkBuf,"");
    const attackFBX=loader.parse(attackBuf,"");
    const hitFBX=loader.parse(hitBuf,"");
    const crawlFBX=loader.parse(crawlBuf,"");
    const standFBX=loader.parse(standBuf,"");

    if(!walkFBX.animations?.length) throw new Error("Zombie Walk sem animação.");
    if(!attackFBX.animations?.length) throw new Error("Zombie Attack sem animação.");
    if(!hitFBX.animations?.length) throw new Error("Zombie Reaction Hit sem animação.");
    if(!crawlFBX.animations?.length) throw new Error("Zombie Crawl sem animação.");
    if(!standFBX.animations?.length) throw new Error("Zombie Stand Up sem animação.");

    // Build ONE template, then clone it into a small pool.
    // This avoids re-parsing FBX for every zombie and keeps hordes lighter.
    let zombieTemplate=walkFBX;
    let meshCount=tintZombie(THREE,zombieTemplate);
    let visualSource="Zombie Walk.fbx";

    if(meshCount===0) {
      zombieTemplate=skeletonMod.clone(game.trueFirstPerson.model);
      meshCount=tintZombie(THREE,zombieTemplate);
      visualSource="corpo humanoide atual (fallback visual)";
    }

    normalizeZombie(THREE,zombieTemplate);

    const walkClip=stripRootMotion(walkFBX.animations[0]);
    const attackClip=stripRootMotion(attackFBX.animations[0]);
    const hitClip=stripRootMotion(hitFBX.animations[0]);
    const crawlClip=keepVerticalHipsMotion(crawlFBX.animations[0]);
    const standClip=keepVerticalHipsMotion(standFBX.animations[0]);

    walkClip.name="Zombie Walk";
    attackClip.name="Zombie Attack";
    hitClip.name="Zombie Reaction Hit";
    crawlClip.name="Zombie Crawl";
    standClip.name="Zombie Stand Up";

    const STATE={
      HIDDEN:"hidden",
      IDLE:"idle",
      WALK:"walk",
      ATTACK:"attack",
      HIT:"hit",
      CRAWL:"crawl",
      STANDUP:"standup",
      DEAD:"dead"
    };

    const cfg={
      maxWaveSize:(matchMedia("(pointer:coarse)").matches?8:14),
      nextWaveDelay:12000,

      speedMin:1.02,
      speedMax:1.32,
      crawlerChance:.34,
      crawlerSpeedMultiplier:.74,
      crawlStandDistanceMin:2.8,
      crawlStandDistanceMax:4.8,
      turnSpeed:5.0,

      attackRange:1.55,
      stopRange:1.18,
      // V168F — a parte útil do golpe termina antes da cauda estática do clip visual.
      // O dano acontece durante o movimento forte, nunca depois da animação parar.
      attackHitFraction:.38,
      attackRecoverFraction:.70,
      attackStaggerMin:250,
      attackStaggerMax:1050,

      playerDamage:16,
      playerDamageGrace:520,

      axeDamage:34,
      axeRange:2.35,
      axeHalfAngleDeg:68,

      spawnMin:13.5,
      spawnMax:19.0,

      separationRadius:.72,
      separationStrength:1.8,

      // Placed logs are real barriers for the horde.
      zombieRadius:.34,
      crawlerRadius:.27,
      logAvoidDistance:.72,
      logAvoidStrength:1.55,

      nightStart:19,
      nightEnd:5.8
    };

    const hordeRoot=new THREE.Group();
    hordeRoot.name="NightZombieHorde";
    game.scene.add(hordeRoot);

    const zombies=[];
    let zombieSerial=0;

    let playerHp=100;
    let playerDamageGraceUntil=0;

    let waveNumber=0;
    let waveSize=0;
    let waveInProgress=false;
    let nextWaveAt=0;

    // V58 — the automatic zombie budget is spread across the entire
    // in-game night instead of finishing during the first few real seconds.
    let waveSpawned=0;
    let nextBatchAt=0;
    let lastBatchSize=0;

    let nightSchedule=[];
    let nightScheduleIndex=0;
    let scheduledNightDay=0;
    let lastScheduledSpawnReal=0;

    let lastT=performance.now();
    let wasNight=false;

    // V72 performance:
    // avoid touching DOM every render frame and avoid repeated world-matrix /
    // log-collision work for every zombie.
    let lastHudUpdateAt=0;
    let lastHudText="";
    let lastNightState=false;

    const LOG_CACHE_REFRESH_MS=1200;
    const cachedLogSegments=[];
    let cachedLogSourceCount=-1;
    let cachedLogRefreshAt=0;

    function isNight() {
      const h=game.dayNight.hour;
      return h>=cfg.nightStart || h<cfg.nightEnd;
    }

    function groundAt(x,z) {
      return game.groundY(x,z);
    }

    function aliveZombies() {
      return zombies.filter(z=>z.alive);
    }

    function aliveCount() {
      let n=0;
      for(const z of zombies) if(z.alive) n++;
      return n;
    }

    function automaticAliveCount(){
      let n=0;

      for(const z of zombies){
        if(z.alive&&!z.manual)n++;
      }

      return n;
    }

    function manualAliveCount(){
      let n=0;

      for(const z of zombies){
        if(z.alive&&z.manual)n++;
      }

      return n;
    }

    function setHudText(text){
      if(!hudState || text===lastHudText)return;
      lastHudText=text;
      hudState.textContent=text;
    }

    function updateHud(
      now=performance.now(),
      force=false
    ){
      if(!hudState)return;

      // UI text does not need 60 DOM writes/second.
      if(
        !force &&
        now-lastHudUpdateAt<250
      )return;

      lastHudUpdateAt=now;

      if(!isNight()){
        setHudText(
          `Dia ${currentSurvivalDay()} • aguardando a noite`
        );
        return;
      }

      const alive=
        automaticAliveCount();

      const manualAlive=
        manualAliveCount();

      if(waveInProgress){
        const waiting=
          Math.max(
            0,
            waveSize-waveSpawned
          );

        const nextEvent=
          nightSchedule[
            nightScheduleIndex
          ];

        let nextText="";

        if(nextEvent){
          const gameMinutes=
            Math.max(
              0,
              Math.ceil(
                (
                  nextEvent.at-
                  nightElapsedHours()
                )*60
              )
            );

          nextText=
            ` • próximo em ~${gameMinutes} min do jogo`;
        }else{
          nextText=
            " • todos os previstos já surgiram";
        }

        setHudText(
          `Dia ${currentSurvivalDay()} • noite • ${alive} vivo${alive===1?"":"s"} • ${waveSpawned}/${waveSize} surgiram`+
          (
            waiting
              ? ` • ${waiting} ainda virão`
              : ""
          )+
          nextText+
          (
            manualAlive
              ? ` • ${manualAlive} manual`
              : ""
          )
        );

        return;
      }

      setHudText(
        `Dia ${currentSurvivalDay()} • noite continua`
      );
    }

    function updatePlayerHp() {
      const maxHp=
        window.gameProgression?.getMaxHealth?.() ?? 100;

      playerHp=clamp(playerHp,0,maxHp);

      if(hpText){
        hpText.textContent=
          `${Math.round(playerHp)} / ${Math.round(maxHp)}`;
      }

      if(hpBar){
        hpBar.style.width=
          `${maxHp>0 ? (playerHp/maxHp)*100 : 0}%`;
      }
    }

    function flashDamage() {
      if(!damageFlash)return;
      damageFlash.style.opacity="1";
      setTimeout(()=>damageFlash.style.opacity="0",110);
    }

    function damagePlayer(z,amount=cfg.playerDamage,sourceLabel="Zumbi da horda") {
      if(z?.duoTarget&&window.FlorestaOnline?.connected&&window.FlorestaOnline.isHost){
        window.FlorestaOnline.send('zombie-player-hit',{id:String(z.id),amount,serial:++duoDamageSerial});return true;
      }
      if(window.gameTestMode?.active && window.gameTestMode?.invulnerable) return false;
      amount=Math.max(0,amount)*(window.gameDifficulty?.preset?.enemyDamage||1);
      const now=performance.now();
      if(playerHp<=0 || now<playerDamageGraceUntil)return false;

      // V168E — timed parry is checked at the single player-damage gateway.
      // Shield blocking remains separate and continues to reduce damage normally.
      const parryResult=window.gameParry?.consumeIncomingAttack?.({
        amount,sourceLabel,sourceId:z?.id
      });
      if(parryResult?.parried)return false;

      playerDamageGraceUntil=now+cfg.playerDamageGrace;
      const rawDamage=Math.max(0,Number(amount)||0);

      const resistedDamage=
        window.gameProgression?.reduceIncomingDamage?.(rawDamage)
        ?? rawDamage;

      const applied=
        window.gameShield
          ?.reduceIncomingDamage?.(
            resistedDamage,
            sourceLabel,
            z?.id
          )
        ?? resistedDamage;

      const finalDamage=window.gameHerbalAlchemy?.reducePotionDamage?.(applied,sourceLabel)??applied;
      playerHp-=finalDamage;
      updatePlayerHp();
      flashDamage();

      window.dispatchEvent(new CustomEvent("game:player-damaged",{
        detail:{
          damage:finalDamage,
          source:String(sourceLabel||"enemy"),
          zombieId:z.id,
          playerHp:Math.max(0,playerHp)
        }
      }));

      if(status) {
        status.textContent=
          `${sourceLabel} te acertou • vida ${Math.max(0,Math.round(playerHp))}`;
      }

      if(playerHp<=0) {
        if(hudState)hudState.textContent="Você caiu • a horda continua";
        setTimeout(()=>{
          playerHp=
            window.gameProgression?.getMaxHealth?.() ?? 100;
          updatePlayerHp();
          if(status)status.textContent="Vida restaurada para continuar o teste";
        },2500);
      }
      return true;
    }

    function makeZombie() {
      zombieSerial++;

      const model=skeletonMod.clone(zombieTemplate);
      model.visible=true;

      const root=new THREE.Group();
      root.name=`HordeZombie_${zombieSerial}`;
      root.visible=false;
      root.add(model);
      hordeRoot.add(root);

      const mixer=new THREE.AnimationMixer(model);
      const walkAction=mixer.clipAction(walkClip);
      const attackAction=mixer.clipAction(attackClip);
      const hitAction=mixer.clipAction(hitClip);
      const crawlAction=mixer.clipAction(crawlClip);
      const standAction=mixer.clipAction(standClip);

      walkAction.setLoop(THREE.LoopRepeat,Infinity);
      crawlAction.setLoop(THREE.LoopRepeat,Infinity);
      attackAction.setLoop(THREE.LoopOnce,1);
      attackAction.clampWhenFinished=true;
      hitAction.setLoop(THREE.LoopOnce,1);
      hitAction.clampWhenFinished=true;
      standAction.setLoop(THREE.LoopOnce,1);
      standAction.clampWhenFinished=true;

      const z={
        id:zombieSerial,
        root,model,mixer,
        walkAction,attackAction,hitAction,crawlAction,standAction,
        alive:false,
        manual:false,
        state:STATE.HIDDEN,
        hp:100,
        maxHp:100,
        speed:cfg.speedMin,
        crawler:false,
        hasStoodUp:true,
        standDistance:3.6,

        // V72 performance state.
        // Visual fidelity stays the same for zombies on screen.
        animAccum:0,
        shadowNear:true,
        steerX:0,
        steerZ:0,
        steerReady:false,
        steerAccum:0,
        separationMoved:false,
        lastPlayerDist:999,
        lastInView:false,

        attackDamageDone:false,
        attackCooldown:0,
        attackStartedAt:0,
        attackHitAt:0,
        attackEndAt:0,
        visualAttackDuration:0,
        lastSwing:-1
      };

      mixer.addEventListener("finished",e=>{
        if(!z.alive||duoGuest())return;

        if(e.action===z.hitAction) {
          if(z.hp<=0) {
            despawnZombie(z,true);
          } else if(isNight()||z.manual) {
            playMove(z,.08);
          } else {
            despawnZombie(z,false);
          }
        } else if(e.action===z.attackAction) {
          // V168F: o fim do ataque é controlado pelo relógio do clip VISUAL,
          // não pelo FBX legado invisível. updateZombieAI() faz a saída exata.
        } else if(e.action===z.standAction) {
          z.hasStoodUp=true;
          z.crawler=false;
          if(z.alive&&(isNight()||z.manual))playWalk(z,.06);
        }
      });

      z.meshes=[];
      z.model.traverse?.(o=>{
        if(o?.isMesh)z.meshes.push(o);
      });

      zombies.push(z);
      return z;
    }

    function ensurePool(count) {
      while(zombies.length<count) makeZombie();
    }

    function stopZombieActions(z) {
      z.walkAction.stop();
      z.attackAction.stop();
      z.hitAction.stop();
      z.crawlAction.stop();
      z.standAction.stop();
    }

    function playIdle(z,fade=.10) {
      if(!z.alive || z.state===STATE.IDLE)return;
      z.walkAction.fadeOut?.(fade);
      z.crawlAction.fadeOut?.(fade);
      z.attackAction.stop();
      z.hitAction.stop();
      z.standAction.stop();
      z.state=STATE.IDLE;
      // O visual V100 possui Idle real. Forçamos a troca aqui para nunca
      // deixar o zumbi congelado no último frame de Attack.
      if(z._v100Visual){
        try{z._v100Visual.play('Idle',fade);z._v100State='Idle';}catch(_){}
      }
    }

    function playWalk(z,fade=.12) {
      if(!z.alive || z.state===STATE.WALK)return;
      z.attackAction.stop();
      z.hitAction.stop();
      z.crawlAction.stop();
      z.standAction.stop();
      z.walkAction.reset().fadeIn(fade).play();
      z.state=STATE.WALK;
    }

    function playCrawl(z,fade=.12) {
      if(!z.alive || z.state===STATE.CRAWL)return;
      z.walkAction.stop();
      z.attackAction.stop();
      z.hitAction.stop();
      z.standAction.stop();
      z.crawlAction.reset().fadeIn(fade).play();
      z.state=STATE.CRAWL;
    }

    function playMove(z,fade=.12) {
      if(z.crawler && !z.hasStoodUp) playCrawl(z,fade);
      else playWalk(z,fade);
    }

    function playStandUp(z) {
      if(
        !z.alive ||
        z.hasStoodUp ||
        z.state===STATE.STANDUP ||
        z.state===STATE.HIT ||
        z.state===STATE.DEAD
      ) return;

      z.crawlAction.fadeOut(.06);
      z.walkAction.stop();
      z.attackAction.stop();
      z.hitAction.stop();
      z.standAction.reset().fadeIn(.035).play();
      z.state=STATE.STANDUP;
    }

    function getVisualAttackDuration(z){
      try{
        const d=z?._v100Visual?.actions?.Attack?.getClip?.()?.duration;
        if(Number.isFinite(d)&&d>.1)return d;
      }catch(_){}
      const fallback=[2.633333444595337,2.4382717079586453,3.511111259460449,2.633333444595337];
      return fallback[Math.abs((Number(z?.id)||1)-1)%fallback.length];
    }

    function finishZombieAttack(z,dist=Infinity){
      if(!z?.alive || z.state!==STATE.ATTACK)return;
      z.attackDamageDone=true;
      z.attackAction.stop();
      if(z.crawler&&!z.hasStoodUp)playCrawl(z,.07);
      else if(dist>cfg.stopRange+.08)playWalk(z,.07);
      else playIdle(z,.07);
    }

    function playAttack(z) {
      if(
        !z.alive ||
        z.state===STATE.ATTACK ||
        z.state===STATE.HIT ||
        z.state===STATE.DEAD
      ) return;

      z.walkAction.fadeOut(.05);
      z.crawlAction.fadeOut(.05);
      z.standAction.stop();
      z.hitAction.stop();

      const visualAttackDuration=getVisualAttackDuration(z);
      const activeDuration=Math.max(.28,visualAttackDuration*cfg.attackRecoverFraction);
      const legacyAttackDuration=Math.max(.001,attackClip.duration);

      // O FBX antigo fica apenas como relógio/compatibilidade e termina junto
      // com a parte ATIVA do golpe, não com a cauda parada do clip novo.
      z.attackAction
        .reset()
        .setEffectiveTimeScale(legacyAttackDuration/activeDuration)
        .fadeIn(.03)
        .play();

      const now=performance.now();
      z.visualAttackDuration=visualAttackDuration;
      z.attackStartedAt=now;
      z.attackHitAt=now+visualAttackDuration*cfg.attackHitFraction*1000;
      z.attackEndAt=now+activeDuration*1000;
      z.state=STATE.ATTACK;
      z.attackDamageDone=false;

      // Reinicia explicitamente o Attack visual em CADA golpe. Isso impede
      // o asset de permanecer travado no último frame entre dois ataques.
      if(z._v100Visual){
        try{z._v100Visual.play('Attack',.045);z._v100State='Attack';}catch(_){}
      }

      const stagger=
        cfg.attackStaggerMin +
        Math.random()*(cfg.attackStaggerMax-cfg.attackStaggerMin);

      z.attackCooldown=
        now +
        activeDuration*1000 +
        Math.max(180,stagger*(window.gameDifficulty?.preset?.zombieRecovery||1));
    }

    function playHitReaction(z) {
      if(!z.alive || z.state===STATE.DEAD)return;

      z.walkAction.stop();
      z.crawlAction.stop();
      z.standAction.stop();
      z.attackAction.stop();
      z.hitAction.reset().fadeIn(.02).play();
      z.state=STATE.HIT;
    }

    function despawnZombie(z,dead=false) {
      if(!z)return;
      stopZombieActions(z);

      const deathPosition=z.root.position.clone();

      z.alive=false;
      z.manual=false;
      z.root.visible=false;
      z.state=dead?STATE.DEAD:STATE.HIDDEN;
      z.hp=0;

      if(dead){
        window.gameProgression?.dropXP?.(
          25,
          deathPosition,
          "Zumbi"
        );
      }

      if(dead && status) {
        status.textContent=
          `Zumbi abatido • ${Math.max(0,aliveCount())} restantes na horda`;
      }
    }

    function clearHorde(includeManual=false) {
      for(const z of zombies) {
        if(
          (z.alive||z.root.visible) &&
          (includeManual||!z.manual)
        ){
          despawnZombie(z,false);
        }
      }
      waveInProgress=false;
    }

    function findSpawnPoint(index,total) {
      // Spread the horde around the player instead of stacking everybody
      // in one spot. Each wave surrounds the clearing from several angles.
      const baseAngle=(index/Math.max(1,total))*Math.PI*2;
      const jitter=(Math.random()-.5)*.48;
      const angle=baseAngle+jitter;
      const radius=
        cfg.spawnMin+Math.random()*(cfg.spawnMax-cfg.spawnMin);

      return {
        x:game.player.x+Math.sin(angle)*radius,
        z:game.player.z+Math.cos(angle)*radius
      };
    }

    function currentSurvivalDay(){
      return Math.max(
        1,
        Number(game.dayNight?.day)||1
      );
    }

    function maxWavesForDay(day=currentSurvivalDay()){
      // V58 has one continuous "night encounter", not several waves that
      // finish early. The difficulty is the total nightly budget.
      return 1;
    }

    function waveSizeForDay(
      day=currentSurvivalDay(),
      wave=1
    ){
      // Calm start, then steady progression:
      // D1 4, D2 6, D3 8, D4 10, D5 12 ... capped at 18.
      return Math.min(
        18,
        4+
        Math.max(0,day-1)*2
      );
    }

    function nightElapsedHours(){
      const h=Number(game.dayNight?.hour)||0;

      // Night is 19:00 -> 05:48 (5.8).
      return h>=19
        ? h-19
        : 5+h;
    }

    const NIGHT_LENGTH_HOURS=10.8;

    function buildNightSchedule(
      day,
      total,
      startElapsed=
        nightElapsedHours()
    ){
      let remaining=Math.max(0,total);
      const groups=[];

      // Groups are deliberately 1–2 only.
      while(remaining>0){
        const twoChance=
          Math.min(
            .48,
            .18+
            Math.max(0,day-1)*.035
          );

        let count=
          (
            remaining>=2 &&
            Math.random()<twoChance
          )
            ? 2
            : 1;

        count=Math.min(
          count,
          remaining
        );

        groups.push(count);
        remaining-=count;
      }

      const schedule=[];
      const n=groups.length;

      // If the player manually jumps to midnight, spread remaining encounters
      // from the CURRENT game-time to dawn instead of instantly catching up.
      const start=
        Math.min(
          NIGHT_LENGTH_HOURS-.65,
          Math.max(
            startElapsed+.18,
            startElapsed+
            .18+
            Math.random()*.28
          )
        );

      const end=
        Math.max(
          start+.20,
          Math.min(
            NIGHT_LENGTH_HOURS-.28,
            9.95+
            Math.random()*.42
          )
        );

      let previous=
        start-.2;

      for(let i=0;i<n;i++){
        const base=
          n===1
            ? (start+end)*.5
            : start+
              (end-start)*
              (i/(n-1));

        const jitter=
          i===0||i===n-1
            ? 0
            : (Math.random()-.5)*.48;

        let at=
          clamp(
            base+jitter,
            start,
            end
          );

        // Never place two automatic groups at the exact same in-game moment.
        at=Math.max(
          at,
          previous+.20
        );

        at=Math.min(
          at,
          NIGHT_LENGTH_HOURS-.18
        );

        schedule.push({
          at,
          count:groups[i]
        });

        previous=at;
      }

      return schedule;
    }

    function spawnAutomaticZombie(
      waveIndex,
      totalInWave
    ){
      let z=zombies.find(x=>!x.alive);

      if(!z){
        ensurePool(
          zombies.length+1
        );

        z=zombies.find(x=>!x.alive);
      }

      if(!z)return false;

      const p=
        findSpawnPoint(
          waveIndex,
          totalInWave
        );

      stopZombieActions(z);

      z.hp=100;
      z.alive=true;
      z.manual=false;
      z.state=STATE.HIDDEN;

      z.crawler=
        Math.random()<
        cfg.crawlerChance;

      z.hasStoodUp=
        !z.crawler;

      z.standDistance=
        cfg.crawlStandDistanceMin+
        Math.random()*
        (
          cfg.crawlStandDistanceMax-
          cfg.crawlStandDistanceMin
        );

      z.speed=
        (
          cfg.speedMin+
          Math.random()*
          (
            cfg.speedMax-
            cfg.speedMin
          )
        )*
        (
          z.crawler
            ? cfg.crawlerSpeedMultiplier
            : 1
        );

      z.animAccum=0;
      z.steerAccum=0;
      z.steerReady=false;
      z.separationMoved=false;
      z.shadowNear=true;

      for(const mesh of z.meshes||[]){
        mesh.castShadow=true;
      }

      z.attackDamageDone=false;
      z.attackStartedAt=0;
      z.attackHitAt=0;
      z.attackEndAt=0;
      z.visualAttackDuration=0;

      z.attackCooldown=
        performance.now()+
        400+
        Math.random()*1100;

      z.lastSwing=-1;

      z.root.position.set(
        p.x,
        groundAt(p.x,p.z),
        p.z
      );

      z.root.rotation.set(
        0,
        Math.random()*Math.PI*2,
        0
      );

      z.root.visible=true;
      playMove(z,0);

      return true;
    }

    function spawnScheduledGroup(
      event,
      now=performance.now()
    ){
      if(
        !waveInProgress||
        !event||
        !isNight()
      )return 0;

      // If the player used very fast time and several events became overdue,
      // still leave a brief real-time gap instead of dumping them in one frame.
      if(
        lastScheduledSpawnReal &&
        now-lastScheduledSpawnReal<900
      ){
        return 0;
      }

      let spawned=0;

      for(let i=0;i<event.count;i++){
        if(
          spawnAutomaticZombie(
            waveSpawned+spawned,
            waveSize
          )
        ){
          spawned++;
        }
      }

      if(!spawned)return 0;

      waveSpawned+=spawned;
      lastBatchSize=spawned;
      lastScheduledSpawnReal=now;

      if(status){
        const remaining=
          Math.max(
            0,
            waveSize-waveSpawned
          );

        status.textContent=
          `${spawned} zumbi${spawned===1?" apareceu":"s apareceram"} na escuridão`+
          (
            remaining
              ? ` • ${remaining} previstos até amanhecer`
              : " • últimos previstos desta noite"
          );
      }

      return spawned;
    }

    function spawnWave() {
      if(!isNight())return false;

      const day=currentSurvivalDay();

      waveNumber=1;
      waveSize=
        waveSizeForDay(day,1);

      ensurePool(
        Math.max(
          cfg.maxWaveSize,
          aliveCount()+
          Math.min(
            waveSize,
            6
          )
        )
      );

      waveSpawned=0;
      lastBatchSize=0;
      waveInProgress=true;
      nextWaveAt=Infinity;
      nextBatchAt=0;
      lastScheduledSpawnReal=0;
      scheduledNightDay=day;

      nightSchedule=
        buildNightSchedule(
          day,
          waveSize,
          nightElapsedHours()
        );

      nightScheduleIndex=0;

      if(status){
        status.textContent=
          day===1
            ? `Primeira noite • ${waveSize} zumbis espalhados até amanhecer`
            : `Dia ${day} • ${waveSize} zumbis previstos ao longo de toda a noite`;
      }

      updateHud(performance.now(),true);
      return true;
    }

    function scheduleNextWave(now=performance.now()) {
      // V58 intentionally has no second compressed wave. The nightly schedule
      // itself spans the whole night.
      waveInProgress=false;
      nextWaveAt=Infinity;
      nextBatchAt=0;

      if(status){
        status.textContent=
          `Dia ${currentSurvivalDay()} • últimos zumbis previstos já apareceram`;
      }
    }

    // ----------------------------------------------------------
    // PLACED LOGS = SOLID ZOMBIE BARRIERS
    // A placed trunk is represented as a horizontal capsule using the
    // same length/radius already stored by the lumber system.
    // ----------------------------------------------------------
    const logA=new THREE.Vector3();
    const logB=new THREE.Vector3();
    const logClosest=new THREE.Vector3();

    function placedLogs(){
      return window.gameLumber?.placedLogs || [];
    }

    function refreshLogCache(
      now=performance.now(),
      force=false
    ){
      const logs=placedLogs();

      if(
        !force &&
        logs.length===cachedLogSourceCount &&
        now-cachedLogRefreshAt<LOG_CACHE_REFRESH_MS
      ){
        return cachedLogSegments;
      }

      cachedLogRefreshAt=now;
      cachedLogSourceCount=logs.length;
      cachedLogSegments.length=0;

      for(const mesh of logs){
        if(
          !mesh?.parent ||
          mesh.visible===false
        )continue;

        const len=
          Math.max(
            .4,
            Number(mesh.userData.length)||3.0
          );

        const rad=
          Math.max(
            .10,
            Number(mesh.userData.radius)||.22
          );

        // A placed trunk is static. Matrix/world endpoints are therefore
        // computed once and cached instead of once per zombie per frame.
        mesh.updateWorldMatrix?.(true,false);

        const a=
          new THREE.Vector3(
            0,
            -len*.5,
            0
          )
          .applyMatrix4(mesh.matrixWorld);

        const b=
          new THREE.Vector3(
            0,
            len*.5,
            0
          )
          .applyMatrix4(mesh.matrixWorld);

        cachedLogSegments.push({
          ax:a.x,
          az:a.z,
          bx:b.x,
          bz:b.z,
          rad,
          minX:Math.min(a.x,b.x)-rad-1.2,
          maxX:Math.max(a.x,b.x)+rad+1.2,
          minZ:Math.min(a.z,b.z)-rad-1.2,
          maxZ:Math.max(a.z,b.z)+rad+1.2
        });
      }

      return cachedLogSegments;
    }

    function pointSegmentData(
      px,pz,
      seg
    ){
      const abx=seg.bx-seg.ax;
      const abz=seg.bz-seg.az;
      const ab2=abx*abx+abz*abz;

      let t=0;

      if(ab2>.000001){
        t=clamp(
          (
            (px-seg.ax)*abx+
            (pz-seg.az)*abz
          )/ab2,
          0,1
        );
      }

      const cx=
        seg.ax+abx*t;

      const cz=
        seg.az+abz*t;

      const dx=px-cx;
      const dz=pz-cz;

      return {
        cx,cz,dx,dz,t,
        dist:Math.hypot(dx,dz)
      };
    }

    function pointSegmentDistance(
      px,pz,
      ax,az,
      bx,bz
    ){
      const abx=bx-ax;
      const abz=bz-az;
      const ab2=abx*abx+abz*abz;

      let t=0;

      if(ab2>.000001){
        t=clamp(
          (
            (px-ax)*abx+
            (pz-az)*abz
          )/ab2,
          0,1
        );
      }

      const cx=ax+abx*t;
      const cz=az+abz*t;

      return Math.hypot(
        px-cx,
        pz-cz
      );
    }

    function zombieRadius(z){
      return z.crawler&&!z.hasStoodUp
        ? cfg.crawlerRadius
        : cfg.zombieRadius;
    }

    // Hard collision: after movement, a zombie is pushed outside every
    // placed-log capsule. This guarantees it cannot phase through a wall.
    function resolveZombieLogCollision(
      z,
      now=performance.now()
    ){
      const logs=refreshLogCache(now);
      if(!logs.length)return;

      const zr=zombieRadius(z);
      const px=z.root.position.x;
      const pz=z.root.position.z;

      for(const seg of logs){
        const minDist=
          zr+
          seg.rad*.96;

        // Broad phase first: skip almost every distant log without
        // any square root or temporary Three.js object.
        if(
          px<seg.minX-minDist ||
          px>seg.maxX+minDist ||
          pz<seg.minZ-minDist ||
          pz>seg.maxZ+minDist
        )continue;

        const abx=seg.bx-seg.ax;
        const abz=seg.bz-seg.az;
        const ab2=abx*abx+abz*abz;

        let t=0;

        if(ab2>.000001){
          t=clamp(
            (
              (z.root.position.x-seg.ax)*abx+
              (z.root.position.z-seg.az)*abz
            )/ab2,
            0,1
          );
        }

        const cx=seg.ax+abx*t;
        const cz=seg.az+abz*t;

        let nx=z.root.position.x-cx;
        let nz=z.root.position.z-cz;
        let d=Math.hypot(nx,nz);

        if(d>=minDist)continue;

        if(d<.0001){
          nx=-abz;
          nz=abx;
          d=Math.hypot(nx,nz)||1;

          const toPlayerX=
            game.player.x-
            z.root.position.x;

          const toPlayerZ=
            game.player.z-
            z.root.position.z;

          if(
            nx*toPlayerX+
            nz*toPlayerZ>
            0
          ){
            nx=-nx;
            nz=-nz;
          }
        }

        nx/=d;
        nz/=d;

        const push=
          minDist-d+.015;

        z.root.position.x+=nx*push;
        z.root.position.z+=nz*push;
      }
    }

    // Soft steering: before movement, detect a log in the zombie's path and
    // blend the desired direction toward the best end of that log.
    function steerAroundLogs(
      z,
      desiredX,
      desiredZ,
      now=performance.now()
    ){
      const logs=refreshLogCache(now);

      if(!logs.length){
        z.steerX=desiredX;
        z.steerZ=desiredZ;
        z.steerReady=true;
        return;
      }

      const zr=zombieRadius(z);
      let steerX=desiredX;
      let steerZ=desiredZ;

      const lookX=
        z.root.position.x+
        desiredX*cfg.logAvoidDistance;

      const lookZ=
        z.root.position.z+
        desiredZ*cfg.logAvoidDistance;

      for(const seg of logs){
        const trigger=
          zr+
          seg.rad+
          .38;

        if(
          lookX<seg.minX-trigger ||
          lookX>seg.maxX+trigger ||
          lookZ<seg.minZ-trigger ||
          lookZ>seg.maxZ+trigger
        )continue;

        const abx=seg.bx-seg.ax;
        const abz=seg.bz-seg.az;
        const ab2=abx*abx+abz*abz;

        let t=0;

        if(ab2>.000001){
          t=clamp(
            (
              (lookX-seg.ax)*abx+
              (lookZ-seg.az)*abz
            )/ab2,
            0,1
          );
        }

        const cx=seg.ax+abx*t;
        const cz=seg.az+abz*t;

        let nx=lookX-cx;
        let nz=lookZ-cz;
        let nd=Math.hypot(nx,nz);

        if(nd>=trigger)continue;

        const sl=Math.hypot(abx,abz);
        if(sl<.001)continue;

        const tx=abx/sl;
        const tz=abz/sl;

        const dot=
          tx*desiredX+
          tz*desiredZ;

        const side=
          dot>=0?1:-1;

        if(nd<.001){
          nx=-tz;
          nz=tx;
          nd=1;
        }

        nx/=nd;
        nz/=nd;

        const strength=
          clamp(
            1-nd/trigger,
            0,1
          )*
          cfg.logAvoidStrength;

        steerX+=tx*side*strength;
        steerZ+=tz*side*strength;
        steerX+=nx*strength*.72;
        steerZ+=nz*strength*.72;
      }

      const l=
        Math.hypot(
          steerX,
          steerZ
        );

      if(l<.001){
        z.steerX=desiredX;
        z.steerZ=desiredZ;
      }else{
        z.steerX=steerX/l;
        z.steerZ=steerZ/l;
      }

      z.steerReady=true;
    }

    // Logs also block melee through the barrier. A zombie must actually
    // get around the trunk before its attack can damage the player.
    function logBlocksZombieAttack(
      z,
      now=performance.now()
    ){
      const logs=refreshLogCache(now);
      if(!logs.length)return false;

      const ax=z.root.position.x;
      const az=z.root.position.z;
      const target=z.duoTarget||game.player;
      const bx=target.x;
      const bz=target.z;

      const pathX=bx-ax;
      const pathZ=bz-az;
      const path2=
        pathX*pathX+
        pathZ*pathZ;

      if(path2<.0001)return false;

      for(const seg of logs){
        const clearance=
          seg.rad+.16;

        const d1=
          pointSegmentDistance(
            seg.ax,seg.az,
            ax,az,
            bx,bz
          );

        const d2=
          pointSegmentDistance(
            seg.bx,seg.bz,
            ax,az,
            bx,bz
          );

        const cp=
          pointSegmentDistance(
            ax,az,
            seg.ax,seg.az,
            seg.bx,seg.bz
          );

        const cq=
          pointSegmentDistance(
            bx,bz,
            seg.ax,seg.az,
            seg.bx,seg.bz
          );

        if(
          d1<clearance ||
          d2<clearance ||
          cp<clearance ||
          cq<clearance
        ){
          const mx=
            (seg.ax+seg.bx)*.5;

          const mz=
            (seg.az+seg.bz)*.5;

          const t=
            (
              (mx-ax)*pathX+
              (mz-az)*pathZ
            )/path2;

          if(t>0&&t<1)return true;
        }
      }

      return false;
    }

    function targetYawFromDelta(dx,dz) {
      return Math.atan2(dx,dz)+Math.PI;
    }

    function updateZombieAI(
      z,
      dt,
      now,
      heavyAI=false
    ){
      if(!z.alive)return;

      const peer=window.FlorestaOnline?.isHost?window.FlorestaOnline.peerPosition:null;
      // Keep the chosen victim throughout the attack wind-up.
      if(z.state!==STATE.ATTACK){
        z.duoTarget=peer&&peer.zone!=='cave'&&Math.hypot(peer.x-z.root.position.x,peer.z-z.root.position.z)<
          Math.hypot(game.player.x-z.root.position.x,game.player.z-z.root.position.z)?peer:null;
      }else if(z.duoTarget){z.duoTarget=peer&&peer.zone!=='cave'?peer:null;}
      const target=z.duoTarget||game.player;
      const dx=
        target.x-
        z.root.position.x;

      const dz=
        target.z-
        z.root.position.z;

      const dist=
        Math.hypot(dx,dz);

      z.lastPlayerDist=dist;

      if(z.state!==STATE.HIT){
        const desired=
          targetYawFromDelta(
            dx,dz
          );

        const diff=
          wrap(
            desired-
            z.root.rotation.y
          );

        z.root.rotation.y+=
          diff*
          (
            1-
            Math.exp(
              -cfg.turnSpeed*dt
            )
          );
      }

      if(z.state===STATE.HIT)return;
      if(z.state===STATE.STANDUP)return;

      if(
        z.crawler &&
        !z.hasStoodUp &&
        dist<=z.standDistance
      ){
        playStandUp(z);
        return;
      }

      if(z.state===STATE.ATTACK){
        // V168F — UMA única janela de impacto, sincronizada com a parte forte
        // da animação. Fora dessa janela o zumbi nunca causa dano parado.
        if(!z.attackDamageDone && now>=z.attackHitAt){
          z.attackDamageDone=true;
          if(
            now<=z.attackEndAt &&
            dist<=cfg.attackRange+.25 &&
            !logBlocksZombieAttack(z,now)
          ){
            damagePlayer(z);
          }
        }

        if(now>=z.attackEndAt){
          finishZombieAttack(z,dist);
        }
        return;
      }

      if(
        dist<=cfg.attackRange &&
        now>=z.attackCooldown &&
        !logBlocksZombieAttack(
          z,
          now
        )
      ){
        playAttack(z);
        return;
      }

      if(dist>cfg.stopRange){
        playMove(z);

        const inv=
          1/
          Math.max(
            .001,
            dist
          );

        // V182: hard enemies predict a short future path, without seeing through walls.
        // Collision / separation from the original game are preserved.
        const brain=window.gameDifficulty?.preset;
        let pursueX=dx,pursueZ=dz;
        if(!z.duoTarget&&brain?.tier>=2&&dist>4.2&&dist<24){
          const future=window.gameDifficulty.predict(brain.leadSeconds);
          const idN=String(z.id||'0').split('').reduce((n,c)=>(n*33+c.charCodeAt(0))|0,5381);
          const sign=(idN&1)?1:-1;
          // Stable small flanking offset: zombies stop stacking into one straight line.
          const side=brain.tier===3?1.55:1.0;
          const lateral=Math.max(0,Math.min(1,(dist-4.2)/5))*side*sign;
          pursueX=future.x-z.root.position.x + (-dz/Math.max(1,dist))*lateral;
          pursueZ=future.z-z.root.position.z + (dx/Math.max(1,dist))*lateral;
        }
        const pursueD=Math.max(.001,Math.hypot(pursueX,pursueZ));
        const desiredX=pursueX/pursueD;
        const desiredZ=pursueZ/pursueD;

        // Expensive obstacle-steering decisions are cached. Movement itself
        // still runs every render frame, so zombies stay smooth.
        if(
          heavyAI ||
          !z.steerReady
        ){
          steerAroundLogs(
            z,
            desiredX,
            desiredZ,
            now
          );
        }

        const step=
          Math.min(
            dist-cfg.stopRange,
            z.speed*(window.gameDifficulty?.preset?.zombieSpeed||1)*dt
          );

        z.root.position.x+=
          z.steerX*step;

        z.root.position.z+=
          z.steerZ*step;

        resolveZombieLogCollision(
          z,
          now
        );

        z.root.position.y=
          groundAt(
            z.root.position.x,
            z.root.position.z
          );
      } else {
        // Perto do jogador e aguardando cooldown: Idle real, não último frame
        // congelado do ataque nem caminhada parada.
        if(z.crawler&&!z.hasStoodUp)playCrawl(z,.08);
        else playIdle(z,.08);
      }
    }

    function applyZombieSeparation(dt){
      for(const z of zombies){
        z.separationMoved=false;
      }

      for(
        let i=0;
        i<zombies.length;
        i++
      ){
        const a=zombies[i];

        if(!a.alive)continue;

        for(
          let j=i+1;
          j<zombies.length;
          j++
        ){
          const b=zombies[j];

          if(!b.alive)continue;

          let dx=
            a.root.position.x-
            b.root.position.x;

          let dz=
            a.root.position.z-
            b.root.position.z;

          let d=
            Math.hypot(
              dx,dz
            );

          if(
            d>=cfg.separationRadius
          )continue;

          if(d<.001){
            const ang=
              Math.random()*
              Math.PI*2;

            dx=Math.cos(ang)*.01;
            dz=Math.sin(ang)*.01;
            d=.01;
          }

          const overlap=
            cfg.separationRadius-d;

          const push=
            overlap*.5*
            Math.min(
              1,
              cfg.separationStrength*
              dt*
              12
            );

          const nx=dx/d;
          const nz=dz/d;

          a.root.position.x+=nx*push;
          a.root.position.z+=nz*push;
          b.root.position.x-=nx*push;
          b.root.position.z-=nz*push;

          a.separationMoved=true;
          b.separationMoved=true;
        }
      }
    }

    function angleToZombieOk(z) {
      const dx=z.root.position.x-game.player.x;
      const dz=z.root.position.z-game.player.z;
      const len=Math.hypot(dx,dz);

      if(len<.001)return true;

      const tx=dx/len,tz=dz/len;
      const fx=-Math.sin(game.player.yaw);
      const fz=-Math.cos(game.player.yaw);
      const dot=clamp(fx*tx+fz*tz,-1,1);
      const minDot=
        Math.cos(
          THREE.MathUtils.degToRad(cfg.axeHalfAngleDeg)
        );

      return dot>=minDot;
    }

    function findAxeTarget(swing) {
      let best=null;
      let bestScore=Infinity;

      for(const z of zombies) {
        if(
          !z.alive ||
          !z.root.visible ||
          z.state===STATE.DEAD ||
          z.lastSwing===swing
        ) continue;

        const dx=z.root.position.x-game.player.x;
        const dz=z.root.position.z-game.player.z;
        const d=Math.hypot(dx,dz);

        if(d>cfg.axeRange || !angleToZombieOk(z))continue;

        // Prefer the closest zombie near the crosshair/forward direction.
        const tx=dx/Math.max(.001,d);
        const tz=dz/Math.max(.001,d);
        const fx=-Math.sin(game.player.yaw);
        const fz=-Math.cos(game.player.yaw);
        const alignment=fx*tx+fz*tz;

        const score=d-(alignment*.35);
        if(score<bestScore) {
          bestScore=score;
          best=z;
        }
      }

      return best;
    }

    let duoDamageSerial=0,duoBackupZombies=null;
    function duoGuest(){return !!(window.FlorestaOnline?.connected&&!window.FlorestaOnline.isHost);}
    function damageZombie(z,damage){
      if(duoGuest())return window.FlorestaDuoWorld?.requestZombieHit?.(z.id,damage)??false;
      z.hp=Math.max(0,z.hp-damage);playHitReaction(z);return true;
    }
    function applyDuoZombies(records){
      if(!duoGuest()||!Array.isArray(records))return;
      if(duoBackupZombies===null)duoBackupZombies=zombies.map(z=>({z,alive:z.alive,hp:z.hp,state:z.state,visible:z.root.visible,x:z.root.position.x,y:z.root.position.y,zpos:z.root.position.z,yaw:z.root.rotation.y}));
      const count=Math.max(0,...records.map(r=>Number(r.id)||0));
      if(count>90)return;ensurePool(count);
      const lookup=new Map(records.map(r=>[String(r.id),r]));
      for(const z of zombies){
        const r=lookup.get(String(z.id));
        if(!r){z.alive=false;z.root.visible=false;continue;}
        z.alive=r.alive;z.root.visible=r.visible!==false&&r.alive;
        z.hp=Number.isFinite(r.hp)?r.hp:z.hp;z.crawler=!!r.crawler;z.manual=!!r.manual;
        z.state=r.state;z.duoPosition=r;
      }
    }
    function onAxeImpact(e) {
      if(window.gameRightHand?.current!=="axe")return;

      const swing=e.detail?.swingId ?? performance.now();
      const z=findAxeTarget(swing);
      if(!z)return;

      z.lastSwing=swing;
      const axeDamage=(
        window.gameProgression?.modifyAxeDamage?.(cfg.axeDamage)
        ?? cfg.axeDamage
      )*(window.gameParry?.damageMultiplierFor?.(z.id)??1);

      damageZombie(z,axeDamage);

      if(status) {
        status.textContent=
          `Machado acertou zumbi da horda • ${z.hp} HP • ${aliveCount()} vivos`;
      }
    }

    window.addEventListener("game:axe-impact",onAxeImpact);

    function spawnManualZombie(count=1){
      count=Math.max(
        1,
        Math.min(
          10,
          Math.floor(Number(count)||1)
        )
      );

      ensurePool(
        Math.max(
          cfg.maxWaveSize,
          aliveCount()+count
        )
      );

      let spawned=0;

      for(let n=0;n<count;n++){
        const z=zombies.find(x=>!x.alive);
        if(!z)break;

        const angle=
          (game.player.yaw||0)+
          Math.PI+
          (n-(count-1)/2)*.28;

        const radius=7.5+Math.min(4,n*.55);

        const x=
          game.player.x-
          Math.sin(angle)*radius;

        const zz=
          game.player.z-
          Math.cos(angle)*radius;

        stopZombieActions(z);

        z.hp=100;
        z.alive=true;
        z.manual=true;
        z.state=STATE.HIDDEN;
        z.crawler=Math.random()<cfg.crawlerChance;
        z.hasStoodUp=!z.crawler;
        z.standDistance=
          cfg.crawlStandDistanceMin+
          Math.random()*
          (cfg.crawlStandDistanceMax-cfg.crawlStandDistanceMin);

        z.speed=
          (cfg.speedMin+
           Math.random()*
           (cfg.speedMax-cfg.speedMin))*
          (z.crawler?cfg.crawlerSpeedMultiplier:1);

        z.animAccum=0;
        z.steerAccum=0;
        z.steerReady=false;
        z.separationMoved=false;
        z.attackDamageDone=false;
        z.attackStartedAt=0;
        z.attackHitAt=0;
        z.attackEndAt=0;
        z.visualAttackDuration=0;
        z.attackCooldown=
          performance.now()+
          400+
          Math.random()*700;
        z.lastSwing=-1;

        z.root.position.set(
          x,
          groundAt(x,zz),
          zz
        );

        z.root.rotation.set(
          0,
          Math.random()*Math.PI*2,
          0
        );

        z.root.visible=true;
        playMove(z,0);
        spawned++;
      }

      if(status&&spawned){
        status.textContent=
          `${spawned} zumbi${spawned===1?"":"s"} spawnado${spawned===1?"":"s"} manualmente`;
      }

      return spawned;
    }

    function updateNightAndWaves(now) {
      const night=isNight();

      if(!night){
        if(
          wasNight||
          automaticAliveCount()>0
        ){
          clearHorde();

          waveNumber=0;
          waveSize=0;
          waveSpawned=0;
          waveInProgress=false;

          nightSchedule=[];
          nightScheduleIndex=0;
          scheduledNightDay=0;

          nextWaveAt=0;
          nextBatchAt=0;
          lastBatchSize=0;
          lastScheduledSpawnReal=0;
        }

        wasNight=false;
        return;
      }

      const day=currentSurvivalDay();

      // Entering the night, or changing the test day while already at night,
      // creates a fresh schedule from the CURRENT in-game time to dawn.
      if(
        !wasNight||
        scheduledNightDay!==day
      ){
        if(
          scheduledNightDay!==0&&
          scheduledNightDay!==day
        ){
          clearHorde();
        }

        wasNight=true;
        waveNumber=0;
        waveSize=0;
        waveSpawned=0;
        waveInProgress=false;

        nightSchedule=[];
        nightScheduleIndex=0;
        scheduledNightDay=day;

        nextWaveAt=now+350;
        nextBatchAt=0;
        lastBatchSize=0;
        lastScheduledSpawnReal=0;

        if(status){
          status.textContent=
            day===1
              ? "Primeira noite • poucos zumbis, espalhados pela noite inteira"
              : `Noite do Dia ${day} • encontros serão distribuídos até amanhecer`;
        }
      }

      if(
        !waveInProgress&&
        waveNumber===0&&
        now>=nextWaveAt
      ){
        spawnWave();
      }

      if(waveInProgress){
        const elapsed=
          nightElapsedHours();

        const event=
          nightSchedule[
            nightScheduleIndex
          ];

        if(
          event&&
          elapsed>=event.at
        ){
          const spawned=
            spawnScheduledGroup(
              event,
              now
            );

          if(spawned){
            nightScheduleIndex++;
          }
        }

        // Do NOT end the encounter just because the player killed the current
        // zombie. The next scheduled zombie may still be hours later.
        if(
          nightScheduleIndex>=
            nightSchedule.length&&
          waveSpawned>=waveSize&&
          automaticAliveCount()===0
        ){
          scheduleNextWave(now);
        }
      }
    }

    function loop(now){
      requestAnimationFrame(loop);if(window.gameSpiderCave?.active)return;

      const dt=
        Math.min(
          .05,
          Math.max(
            0,
            (now-lastT)/1000
          )
        );

      lastT=now;

      if(duoGuest()){
        for(const z of zombies){
          const r=z.duoPosition;if(!r)continue;
          const blend=1-Math.exp(-18*dt),dist=Math.hypot(z.root.position.x-r.x,z.root.position.z-r.z);
          const alpha=dist>8?1:blend;
          z.root.position.x+=(r.x-z.root.position.x)*alpha;
          z.root.position.y+=(r.y-z.root.position.y)*alpha;
          z.root.position.z+=(r.z-z.root.position.z)*alpha;
          z.root.rotation.y+=Math.atan2(Math.sin(r.yaw-z.root.rotation.y),Math.cos(r.yaw-z.root.rotation.y))*alpha;
          if(z.alive)z.mixer.update(dt);
        }
        return; // Host alone spawns waves and integrates zombie AI.
      }
      if(duoBackupZombies!==null){
        for(const z of zombies){z.duoPosition=null;z.duoTarget=null;z.alive=false;z.root.visible=false;}
        for(const r of duoBackupZombies){const z=r.z;z.alive=r.alive;z.hp=r.hp;z.state=r.state;z.root.visible=r.visible;z.root.position.set(r.x,r.y,r.zpos);z.root.rotation.y=r.yaw;}
        duoBackupZombies=null;
      }
      updateNightAndWaves(now);

      const nightNow=isNight();

      // Refresh static log data once, not once per zombie/collision test.
      refreshLogCache(now);

      const yaw=
        game.player.yaw||0;

      const viewX=
        -Math.sin(yaw);

      const viewZ=
        -Math.cos(yaw);

      for(const z of zombies){
        if(!z.alive)continue;
        if(!nightNow&&!z.manual)continue;

        const dxp=
          game.player.x-
          z.root.position.x;

        const dzp=
          game.player.z-
          z.root.position.z;

        const playerDist=
          Math.hypot(
            dxp,dzp
          );

        const toZombieX=-dxp;
        const toZombieZ=-dzp;

        const viewDot=
          playerDist>.001
            ? (
                viewX*toZombieX+
                viewZ*toZombieZ
              )/playerDist
            : 1;

        // On-screen zombies keep the same visual animation cadence.
        // Off-screen zombies can be evaluated less often because the player
        // literally cannot see those intermediate skeleton poses.
        const inView=
          playerDist<4.0 ||
          viewDot>-.08;

        z.lastInView=inView;

        const animStep=
          inView
            ? (
                playerDist>17
                  ? 1/15
                  : playerDist>9
                    ? 1/30
                    : 1/60
              )
            : 1/12;

        z.animAccum+=dt;

        if(
          z.animAccum>=animStep
        ){
          z.mixer.update(
            Math.min(
              .12,
              z.animAccum
            )
          );

          z.animAccum=0;
        }

        const shouldShadow=
          playerDist<13;

        if(
          shouldShadow!==
          z.shadowNear
        ){
          z.shadowNear=
            shouldShadow;

          for(
            const mesh of
            z.meshes||[]
          ){
            mesh.castShadow=
              shouldShadow;
          }
        }

        // Steering/obstacle decisions do not need 60 Hz. Position/movement
        // is still integrated every frame, so no visible stepping is added.
        const steerStep=
          playerDist>14
            ? 1/16
            : 1/30;

        z.steerAccum+=dt;

        const heavyAI=
          z.steerAccum>=
          steerStep;

        if(heavyAI){
          z.steerAccum=0;
        }

        updateZombieAI(
          z,
          dt,
          now,
          heavyAI
        );
      }

      applyZombieSeparation(dt);

      // Only zombies actually moved by separation need a second collision
      // correction. V58 did this for the entire horde every frame.
      for(const z of zombies){
        if(
          !z.alive ||
          !z.separationMoved
        )continue;

        resolveZombieLogCollision(
          z,
          now
        );

        z.root.position.y=
          groundAt(
            z.root.position.x,
            z.root.position.z
          );
      }

      updateHud(now);
    }

    updatePlayerHp();

    wasNight=false;
    scheduledNightDay=0;

    if(isNight()) {
      nextWaveAt=performance.now()+350;
      if(status){
        status.textContent=
          "Noite ativa • distribuindo encontros até amanhecer";
      }
    } else {
      if(hudState)hudState.textContent="Horda: aguardando a noite";
    }

    requestAnimationFrame(loop);if(window.gameSpiderCave?.active)return;

    window.gameZombie={
      applyDuoZombies,
      damageNetwork(id,amount){const z=zombies.find(z=>String(z.id)===String(id)&&z.alive);return z?damageZombie(z,amount):false;},
 combatTargets(){return zombies.filter(z=>z.alive&&z.root.visible).map(z=>({root:z.root,radius:.43,height:z.crawler?.45:1.0,hit(damage){return damageZombie(z,damage*(window.gameParry?.damageMultiplierFor?.(z.id)??1));}}));},
      get active(){return aliveCount()>0;},
      get state(){return aliveCount()>0?"horde":"hidden";},
      get hp(){
        const first=zombies.find(z=>z.alive);
        return first?.hp ?? 0;
      },
      get playerHp(){return playerHp;},
      get maxPlayerHp(){
        return window.gameProgression?.getMaxHealth?.() ?? 100;
      },
      refreshPlayerHp(){
        updatePlayerHp();
        return playerHp;
      },
      healPlayer(amount=0){
        const maxHp=
          window.gameProgression?.getMaxHealth?.() ?? 100;

        playerHp=Math.min(
          maxHp,
          playerHp+Math.max(0,Number(amount)||0)
        );

        updatePlayerHp();
        return playerHp;
      },
      get model(){return hordeRoot;},
      get visualSource(){return visualSource;},
      get wave(){return waveNumber;},
      get aliveCount(){return aliveCount();},
      get waveSize(){return waveSize;},
      get waveSpawned(){return waveSpawned;},
      get automaticAliveCount(){return automaticAliveCount();},
      get manualAliveCount(){return manualAliveCount();},
      get nextBatchIn(){
        return Number.isFinite(nextBatchAt)
          ? Math.max(
              0,
              nextBatchAt-performance.now()
            )
          : 0;
      },
      get zombies(){return zombies;},
      get performance(){
        return {
          alive:aliveCount(),
          cachedLogs:cachedLogSegments.length,
          hudHz:4,
          visibleAnimation:"original cadence",
          offscreenAnimationHz:12,
          steeringHzNear:30,
          steeringHzFar:16
        };
      },
      get currentDay(){return currentSurvivalDay();},
      get maxWavesTonight(){return 1;},
      get plannedWaveSize(){
        return waveSizeForDay(
          currentSurvivalDay(),
          1
        );
      },
      get nightlyBudget(){
        return waveSizeForDay(
          currentSurvivalDay(),
          1
        );
      },
      get nightSchedule(){
        return nightSchedule.map(
          e=>({...e})
        );
      },
      get nextSpawnGameMinutes(){
        const e=
          nightSchedule[
            nightScheduleIndex
          ];

        return e
          ? Math.max(
              0,
              Math.ceil(
                (
                  e.at-
                  nightElapsedHours()
                )*60
              )
            )
          : null;
      },
      animations:{
        walk:"Zombie Walk.fbx",
        attack:"Zombie Attack.fbx",
        hit:"Zombie Reaction Hit.fbx",
        crawl:"Zombie Crawl.fbx",
        standUp:"Zombie Stand Up.fbx"
      },
      hurtPlayer(amount=16,sourceLabel="Inimigo",sourceId="external"){
        return damagePlayer(
          {id:String(sourceId||"external")},
          amount,
          sourceLabel
        );
      },
      damageRing(x,z,waveRadius,thickness,baseDamage,maxRadius,sourceLabel="Dano em área",hitSet=null){
        let hits=0;
        const set=hitSet||new Set();
        for(const enemy of zombies){
          if(!enemy?.alive||!enemy.root?.visible||enemy.state===STATE.DEAD||set.has(enemy))continue;
          const d=Math.hypot(enemy.root.position.x-x,enemy.root.position.z-z);
          if(Math.abs(d-waveRadius)>thickness)continue;
          set.add(enemy);
          const falloff=Math.max(.45,1-.5*d/Math.max(.001,maxRadius||waveRadius||1));
          const postureMult=window.gameParry?.damageMultiplierFor?.(enemy.id)??1;
          damageZombie(enemy,Math.max(0,baseDamage)*falloff*postureMult);
          hits++;
        }
        return hits;
      },
      damageRadius(x,z,radius,baseDamage,sourceLabel="Dano em área",hitSet=null){
        let hits=0;
        const set=hitSet||new Set();
        for(const enemy of zombies){
          if(!enemy?.alive||!enemy.root?.visible||enemy.state===STATE.DEAD||set.has(enemy))continue;
          const d=Math.hypot(enemy.root.position.x-x,enemy.root.position.z-z);
          if(d>radius)continue;
          set.add(enemy);
          const falloff=Math.max(.60,1-.40*d/Math.max(.001,radius));
          const postureMult=window.gameParry?.damageMultiplierFor?.(enemy.id)??1;
          damageZombie(enemy,Math.max(0,baseDamage)*falloff*postureMult);
          hits++;
        }
        return hits;
      },
      spawnNow(){
        clearHorde();
        waveInProgress=false;
        nextWaveAt=0;
        return spawnWave();
      },
      spawnManual(count=1){
        return spawnManualZombie(count);
      },
      spawnOne(){
        return spawnManualZombie(1);
      },
      nextWave(){
        clearHorde();
        waveNumber=0;
        waveInProgress=false;
        nightSchedule=[];
        nightScheduleIndex=0;
        scheduledNightDay=currentSurvivalDay();
        return spawnWave();
      },
      despawn(){
        clearHorde(true);
      }
    };

    window.gameHorde=window.gameZombie;

    if(status) {
      status.textContent=
        `Sistema de hordas pronto • ~${Math.round(cfg.crawlerChance*100)}% podem rastejar`;
    }
  } catch(err) {
    console.error("Horda de zumbis:",err);
    if(hudState)hudState.textContent="Horda: erro ao carregar";
    if(status) {
      status.textContent+=
        " • hordas indisponíveis: "+
        String(err?.message||err);
    }
  }
})();
